// ---------------------------------------------------------------------------
// Lean spec reference implementations (pure, using the same types as Go)
// ---------------------------------------------------------------------------

// leanEffectiveMaxBitRate mirrors BitrateControl.lean effectiveMaxBitRate.
// Lean uses Int; we use float64 (Ubps) to match the Go type.
func leanEffectiveMaxBitRate(minBitRate, maxBitRate, inputBitRate types.Ubps) types.Ubps {
	if inputBitRate > minBitRate*2 && 1.5*inputBitRate < maxBitRate {
		return 1.5 * inputBitRate
	}
	return maxBitRate
}

// leanClampBitRate mirrors BitrateControl.lean clampBitRate.
func leanClampBitRate(minBitRate, maxBitRate, inputBitRate, bitrate types.Ubps) types.Ubps {
	mx := leanEffectiveMaxBitRate(minBitRate, maxBitRate, inputBitRate)
	if bitrate < minBitRate {
		return minBitRate
	}
	if bitrate > mx {
		return mx
	}
	return bitrate
}

// leanShouldEnableBypass mirrors BitrateControl.lean shouldEnableBypass.
func leanShouldEnableBypass(bitrate, inputBitRate types.Ubps) bool {
	return 5*bitrate > 6*inputBitRate
}

// leanShouldDisableBypass mirrors BitrateControl.lean shouldDisableBypass.
func leanShouldDisableBypass(bitrate, inputBitRate types.Ubps) bool {
	return bitrate < inputBitRate
}

// ---------------------------------------------------------------------------
// Target 1: clampBitRate / effectiveMaxBitRate
// ---------------------------------------------------------------------------

func TestLeanSpec_EffectiveMaxBitRate(t *testing.T) {
	testCases := []struct {
		name         string
		minBitRate   types.Ubps
		maxBitRate   types.Ubps
		inputBitRate types.Ubps
		wantMax      types.Ubps
	}{
		{
			name:         "input above 2*min and 1.5*input below max: effective max is 1.5*input",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 6_000_000,
			wantMax:      9_000_000,
		},
		{
			name:         "input exactly 2*min: condition fails (not strictly greater)",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 2_000_000,
			wantMax:      24_000_000,
		},
		{
			name:         "input barely above 2*min",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 2_000_001,
			wantMax:      3_000_001.5,
		},
		{
			name:         "1.5*input equals max: condition fails (not strictly less)",
			minBitRate:   1_000_000,
			maxBitRate:   9_000_000,
			inputBitRate: 6_000_000,
			wantMax:      9_000_000,
		},
		{
			name:         "1.5*input barely below max",
			minBitRate:   1_000_000,
			maxBitRate:   9_000_002,
			inputBitRate: 6_000_000,
			wantMax:      9_000_000,
		},
		{
			name:         "input zero",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 0,
			wantMax:      24_000_000,
		},
		{
			name:         "input negative (degenerate)",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: -1,
			wantMax:      24_000_000,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			// Test the Lean reference impl
			got := leanEffectiveMaxBitRate(tc.minBitRate, tc.maxBitRate, tc.inputBitRate)
			testassert.InDelta(t, float64(tc.wantMax), float64(got), 0.01,
				"lean reference: effectiveMax mismatch")

			// Now verify Go production code uses the same logic.
			// We reconstruct the Go clamping inline (from trySetVideoBitrate lines 597-608).
			maxVideoBitRate := tc.maxBitRate
			if tc.inputBitRate > tc.minBitRate*2 && float64(tc.inputBitRate)*1.5 < float64(maxVideoBitRate) {
				maxVideoBitRate = types.Ubps(1.5 * float64(tc.inputBitRate))
			}
			testassert.InDelta(t, float64(tc.wantMax), float64(maxVideoBitRate), 0.01,
				"Go production: effectiveMax mismatch")
		})
	}
}

func TestLeanSpec_ClampBitRate(t *testing.T) {
	testCases := []struct {
		name         string
		minBitRate   types.Ubps
		maxBitRate   types.Ubps
		inputBitRate types.Ubps
		bitrate      types.Ubps
		want         types.Ubps
	}{
		{
			name:         "bitrate within range, no effective-max reduction",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 10_000_000,
			bitrate:      8_000_000,
			want:         8_000_000,
		},
		{
			name:         "bitrate below min: clamped to min",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 10_000_000,
			bitrate:      500_000,
			want:         1_000_000,
		},
		{
			name:         "bitrate above effective max: clamped to effective max",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 6_000_000,
			bitrate:      20_000_000,
			want:         9_000_000, // effective max = 1.5 * 6M = 9M
		},
		{
			name:         "bitrate above max, no effective-max reduction",
			minBitRate:   1_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 20_000_000,
			bitrate:      30_000_000,
			want:         24_000_000,
		},
		{
			name:         "effective max clamping does not go below min",
			minBitRate:   5_000_000,
			maxBitRate:   24_000_000,
			inputBitRate: 12_000_000, // 12M > 2*5M, 18M < 24M => effectiveMax=18M
			bitrate:      20_000_000,
			want:         18_000_000,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			leanResult := leanClampBitRate(tc.minBitRate, tc.maxBitRate, tc.inputBitRate, tc.bitrate)
			testassert.InDelta(t, float64(tc.want), float64(leanResult), 0.01,
				"lean reference: clamp mismatch")

			// Reproduce Go clamping logic (trySetVideoBitrate lines 597-608)
			maxVideoBitRate := tc.maxBitRate
			if tc.inputBitRate > tc.minBitRate*2 && float64(tc.inputBitRate)*1.5 < float64(maxVideoBitRate) {
				maxVideoBitRate = types.Ubps(1.5 * float64(tc.inputBitRate))
			}
			clamped := tc.bitrate
			switch {
			case tc.bitrate < tc.minBitRate:
				clamped = tc.minBitRate
			case tc.bitrate > maxVideoBitRate:
				clamped = maxVideoBitRate
			}
			testassert.InDelta(t, float64(tc.want), float64(clamped), 0.01,
				"Go production: clamp mismatch")
		})
	}
}

